<template>
  <el-drawer
    title="Logo设置"
    :visible.sync="visibleDrawer"
    class="div-form-drawer-wrapper"
    custom-class="div-form-drawer"
    direction="rtl"
    :append-to-body="true"
    :modal="false"
    size="249px"
    :before-close="onBeforeClose"
  >
    <el-form
      ref="divSettingLogoForm"
      :model="model"
      :rules="rules"
      class="logo-setting-form"
    >
      <el-form-item label="品牌LOGO">
        <vr-upload
          uploadClass="logo-container"
          tip="建议尺寸：300 X 144"
          listType
          :showDelAction="true"
          :cropImg="false"
          cropDialogTop="5vh"
          :cropDialogModal="false"
          :cropFixed="false"
          :autoCropWidth="300"
          :autoCropHeight="144"
          :autoUpload="true"
          :fileList="[
            {
              name: '品牌LOGO',
              url: model.logo_full,
              path: model.logo,
            },
          ]"
          @onSuccess="onLogoUploadSuccess"
          @onClearFile="onClearLogoFile"
        />
      </el-form-item>
      <el-form-item label="品牌链接" prop="link_url">
        <el-input
          placeholder="请输入合法的url"
          v-model="model.link_url"
          size="mini"
          style="width: 90%; margin-left: 10px"
        >
        </el-input>
      </el-form-item>
      <el-form-item label="LOGO位置" class="no-margin"></el-form-item>
      <el-form-item>
        <el-radio-group
          v-model="model.logo_position"
          size="mini"
          class="logo_position_radio_group"
        >
          <el-radio-button label="left_top">左上角</el-radio-button>
          <el-radio-button label="left_bottom" disabled>左下角</el-radio-button>
          <el-radio-button label="right_top" disabled>右上角</el-radio-button>
          <el-radio-button label="right_bottom" disabled>右下角</el-radio-button>
        </el-radio-group>
      </el-form-item>
      <el-form-item class="el-form-item-submit">
        <el-button type="primary" @click="submitForm()">保存</el-button>
      </el-form-item>
    </el-form>
  </el-drawer>
</template>

<script>
import { setProductLogo, getProductLogo } from '@/api/vr'
const defaultModel = {
  logo: '',
  logo_full: '',
  logo_position: 'left_top',
  link_url: '',
}
export default {
  name: 'DivLogo',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  data() {
    return {
      visibleDrawer: false,
      model: Object.assign({}, defaultModel),
      rules: {
        link_url: [
          { type: 'url', message: '请输入合法的url地址', trigger: 'blur' }
        ]
      }
    }
  },
  props: {
    productId: null
  },
  methods: {
    async init() {
      await this.getProductLogo()
      this.visibleDrawer = true
    },
    async getProductLogo() {
      const info = await getProductLogo(this.productId)
      if (info) {
        this.model = info
      }
    },
    onBeforeClose() {
      this.visibleDrawer = false
      this.resetForm()
      this.$emit('onLogoSetting', this.visibleDrawer)
    },
    resetForm() {
      this.model = Object.assign({}, defaultModel)
      this.$refs.divSettingLogoForm.resetFields()
    },
    // eslint-disable-next-line no-unused-vars
    onLogoUploadSuccess(data) {
      this.model.logo = data.path
    },
    onClearLogoFile() {
      this.model.logo = ''
    },
    submitForm() {
      this.$refs.divSettingLogoForm.validate((valid) => {
          if (valid) {
            setProductLogo(this.productId, this.model).then((data, message) => {
              console.log('data, message:', data, message)
              this.$message.success('设置成功')
              this.resetForm()
              this.visibleDrawer = false
            })
          } else {
            return false
          }
        })
    }
  },
}
</script>

